//! Renders `src/generated/client/<resource>.rs`: a typed async Rust client
//! calling the REST contract generated by `http.rs`
//! (`docs/05-rest-client-cli.md`, "Typed Rust client"). One method per
//! enabled operation; mutation methods that require a precondition send
//! `If-Match` automatically.

use declarify_core::Operation;
use declarify_schema::ResourceSchema;

use crate::util::module_name;
use crate::OWNERSHIP_MARKER;

pub fn render(resource: &ResourceSchema) -> String {
    let name = &resource.name;
    let module = module_name(name);
    let plural = &resource.plural;
    let has = |op: Operation| resource.operations.contains(&op);

    let mut resource_imports = vec![name.clone()];
    if has(Operation::Create) {
        resource_imports.push(format!("Create{name}Input"));
    }
    if has(Operation::UpdateSpec) {
        resource_imports.push(format!("Replace{name}SpecInput"));
    }
    if has(Operation::UpdateStatus) {
        resource_imports.push(format!("Update{name}StatusInput"));
    }
    resource_imports.sort();

    let mut out = String::new();
    out.push_str(OWNERSHIP_MARKER);
    out.push('\n');
    out.push_str(&format!(
        "use crate::generated::resources::{module}::{{{}}};\n\n",
        resource_imports.join(", ")
    ));

    out.push_str(&format!(
        "/// Typed async REST client for `{name}`. Accepts an injected base URL\n\
         /// and, optionally, `reqwest` client configuration; does not depend on\n\
         /// any CLI code.\n\
         pub struct {name}Client {{\n\
         base_url: String,\n\
         http: reqwest::Client,\n\
         }}\n\n\
         impl {name}Client {{\n\
         pub fn new(base_url: impl Into<String>) -> Self {{\n\
         Self::with_client(base_url, reqwest::Client::new())\n\
         }}\n\n\
         pub fn with_client(base_url: impl Into<String>, http: reqwest::Client) -> Self {{\n\
         Self {{ base_url: base_url.into(), http }}\n\
         }}\n\n"
    ));

    if has(Operation::Create) {
        out.push_str(&format!(
            "pub async fn create(\n\
             &self,\n\
             input: Create{name}Input,\n\
             ) -> Result<{name}, declarify_runtime::http::ClientError> {{\n\
             let response = self\n\
             .http\n\
             .post(format!(\"{{}}/api/v1/{plural}\", self.base_url))\n\
             .json(&input)\n\
             .send()\n\
             .await\n\
             .map_err(declarify_runtime::http::ClientError::Transport)?;\n\
             declarify_runtime::http::parse_json_response(response).await\n\
             }}\n\n"
        ));
    }

    if has(Operation::Get) {
        out.push_str(&format!(
            "pub async fn get(&self, id: &str) -> Result<{name}, declarify_runtime::http::ClientError> {{\n\
             let response = self\n\
             .http\n\
             .get(format!(\"{{}}/api/v1/{plural}/{{id}}\", self.base_url))\n\
             .send()\n\
             .await\n\
             .map_err(declarify_runtime::http::ClientError::Transport)?;\n\
             declarify_runtime::http::parse_json_response(response).await\n\
             }}\n\n"
        ));
    }

    if has(Operation::List) {
        out.push_str(&format!(
            "pub async fn list(\n\
             &self,\n\
             page: declarify_core::PageRequest,\n\
             ) -> Result<declarify_core::Page<{name}>, declarify_runtime::http::ClientError> {{\n\
             let response = self\n\
             .http\n\
             .get(format!(\"{{}}/api/v1/{plural}\", self.base_url))\n\
             .query(&page)\n\
             .send()\n\
             .await\n\
             .map_err(declarify_runtime::http::ClientError::Transport)?;\n\
             declarify_runtime::http::parse_json_response(response).await\n\
             }}\n\n"
        ));
    }

    if has(Operation::UpdateSpec) {
        out.push_str(&format!(
            "pub async fn replace_spec(\n\
             &self,\n\
             id: &str,\n\
             expected_revision: u64,\n\
             input: Replace{name}SpecInput,\n\
             ) -> Result<{name}, declarify_runtime::http::ClientError> {{\n\
             let response = self\n\
             .http\n\
             .put(format!(\"{{}}/api/v1/{plural}/{{id}}\", self.base_url))\n\
             .header(\"If-Match\", format!(\"\\\"{{expected_revision}}\\\"\"))\n\
             .json(&input)\n\
             .send()\n\
             .await\n\
             .map_err(declarify_runtime::http::ClientError::Transport)?;\n\
             declarify_runtime::http::parse_json_response(response).await\n\
             }}\n\n"
        ));
    }

    if has(Operation::UpdateStatus) {
        out.push_str(&format!(
            "pub async fn update_status(\n\
             &self,\n\
             id: &str,\n\
             expected_revision: u64,\n\
             input: Update{name}StatusInput,\n\
             ) -> Result<{name}, declarify_runtime::http::ClientError> {{\n\
             let response = self\n\
             .http\n\
             .put(format!(\"{{}}/api/v1/{plural}/{{id}}/status\", self.base_url))\n\
             .header(\"If-Match\", format!(\"\\\"{{expected_revision}}\\\"\"))\n\
             .json(&input)\n\
             .send()\n\
             .await\n\
             .map_err(declarify_runtime::http::ClientError::Transport)?;\n\
             declarify_runtime::http::parse_json_response(response).await\n\
             }}\n\n"
        ));
    }

    if has(Operation::Delete) {
        out.push_str(&format!(
            "pub async fn delete(\n\
             &self,\n\
             id: &str,\n\
             expected_revision: u64,\n\
             ) -> Result<(), declarify_runtime::http::ClientError> {{\n\
             let response = self\n\
             .http\n\
             .delete(format!(\"{{}}/api/v1/{plural}/{{id}}\", self.base_url))\n\
             .header(\"If-Match\", format!(\"\\\"{{expected_revision}}\\\"\"))\n\
             .send()\n\
             .await\n\
             .map_err(declarify_runtime::http::ClientError::Transport)?;\n\
             declarify_runtime::http::expect_no_content(response).await\n\
             }}\n\n"
        ));
    }

    out.push_str("}\n");

    out
}
